TASK
Decorate a promise with timeout, fallback, and cancellation behavior.

PUBLIC CONTRACT
Module: await load('./index.js'); default export pTimeout, named export TimeoutError.
pTimeout(inputPromise, options) returns a decorated promise with .clear() to cancel its timeout. milliseconds is a positive number; Infinity disables timeout. Before timeout, it adopts the input fulfillment or rejection. When timeout expires, default behavior rejects with TimeoutError; message may be a string, an Error to reject with, or false to resolve undefined. A fallback function can provide a value/promise instead, and exceptions from fallback reject the decorated promise. Cancelable input promises have their .cancel() method called on ordinary timeout.
customTimers supplies {setTimeout, clearTimeout} for controlled timing. The functions follow timer callback/delay and timer-handle conventions. A supplied AbortSignal cancels using its reason, including when already aborted. Settled operations clean up active timers and abort listeners. The input remains a promise whose rejection must be handled.

SOURCE index.js
   1: export class TimeoutError extends Error {
   2: 	name = 'TimeoutError';
   3: 
   4: 	constructor(message, options) {
   5: 		super(message, options);
   6: 		// V8-only, and it does exactly one thing here: it hides this constructor frame from the stack.
   7: 		// eslint-disable-next-line unicorn/no-useless-error-capture-stack-trace, unicorn/no-nonstandard-builtin-properties
   8: 		Error.captureStackTrace?.(this, TimeoutError);
   9: 	}
  10: }
  11: 
  12: const getAbortedReason = signal => signal.reason ?? new DOMException('This operation was aborted.', 'AbortError');
  13: 
  14: export default function pTimeout(promise, options) {
  15: 	const {
  16: 		milliseconds,
  17: 		fallback,
  18: 		message,
  19: 		customTimers = {setTimeout, clearTimeout},
  20: 		signal,
  21: 	} = options;
  22: 
  23: 	let timer;
  24: 	let abortHandler;
  25: 
  26: 	const wrappedPromise = new Promise((resolve, reject) => {
  27: 		if (typeof milliseconds !== 'number' || Math.sign(milliseconds) !== 1) {
  28: 			throw new TypeError(`Expected \`milliseconds\` to be a positive number, got \`${milliseconds}\``);
  29: 		}
  30: 
  31: 		if (signal?.aborted) {
  32: 			reject(getAbortedReason(signal));
  33: 			// The input still needs a rejection handler even though cancellation won.
  34: 			// eslint-disable-next-line unicorn/prefer-then-catch
  35: 			promise.then(resolve, reject);
  36: 			return;
  37: 		}
  38: 
  39: 		if (signal) {
  40: 			abortHandler = () => {
  41: 				reject(getAbortedReason(signal));
  42: 			};
  43: 
  44: 			signal.addEventListener('abort', abortHandler, {once: true});
  45: 		}
  46: 
  47: 		// Use .then() instead of async IIFE to preserve stack traces
  48: 		// eslint-disable-next-line unicorn/prefer-then-catch
  49: 		promise.then(resolve, reject);
  50: 
  51: 		if (milliseconds === Infinity) {
  52: 			return;
  53: 		}
  54: 
  55: 		// We create the error outside of `setTimeout` to preserve the stack trace.
  56: 		const timeoutError = new TimeoutError();
  57: 
  58: 		// `.call(undefined, ...)` is needed for custom timers to avoid context issues
  59: 		timer = customTimers.setTimeout.call(undefined, () => {
  60: 			if (fallback) {
  61: 				try {
  62: 					resolve(fallback());
  63: 				} catch (error) {
  64: 					reject(error);
  65: 				}
  66: 
  67: 				return;
  68: 			}
  69: 
  70: 			if (typeof promise.cancel === 'function') {
  71: 				promise.cancel();
  72: 			}
  73: 
  74: 			if (message === false) {
  75: 				resolve();
  76: 			} else if (message instanceof Error) {
  77: 				reject(message);
  78: 			} else {
  79: 				timeoutError.message = message ?? `Promise timed out after ${milliseconds} milliseconds`;
  80: 				reject(timeoutError);
  81: 			}
  82: 		}, milliseconds);
  83: 	});
  84: 
  85: 	const cancelablePromise = wrappedPromise.finally(() => {
  86: 		cancelablePromise.clear();
  87: 		if (abortHandler && signal) {
  88: 			signal.removeEventListener('abort', abortHandler);
  89: 		}
  90: 	});
  91: 
  92: 	cancelablePromise.clear = () => {
  93: 		// An infinite timeout never creates one, and a custom `clearTimeout` is entitled to reject `undefined`.
  94: 		if (timer === undefined) {
  95: 			return;
  96: 		}
  97: 
  98: 		// `.call(undefined, ...)` is needed for custom timers to avoid context issues
  99: 		customTimers.clearTimeout.call(undefined, timer);
 100: 		timer = undefined;
 101: 	};
 102: 
 103: 	return cancelablePromise;
 104: }

